with lc as (select distinct on (l."teamId") l."teamId" team_id, l."gameId" game_id, g.date, l.forwards||l.defensemen ids, cardinality(l.forwards) f, cardinality(l.defensemen) d, cardinality(l.goalies) gl from "lineCombinations" l join games g on g.id=l."gameId" where l."teamId" in (3,8,68,23) and g.date < '2026-11-13' order by l."teamId", g.date desc) select lc.team_id, lc.game_id, lc.date, lc.f, lc.d, lc.gl, (select count(*) from unnest(lc.ids) x where exists (select 1 from rosters r where r."playerId"=x and r."teamId"=lc.team_id and r."seasonId"=20262027 and r.is_current)) on_cur_roster, (select count(*) from unnest(lc.ids) x where exists (select 1 from forge_player_projections p where p.run_id='26373189-3ebd-4380-b4f4-c6797d469ca9' and p.player_id=x)) projected, (select array_agg(x) from unnest(lc.ids) x where not exists (select 1 from forge_player_projections p where p.run_id='26373189-3ebd-4380-b4f4-c6797d469ca9' and p.player_id=x)) missing from lc
